package com.rpb.reservation.workforce.leave.account;
import static com.rpb.reservation.workforce.leave.account.LeaveAccountDtos.*;
import com.rpb.reservation.workforce.compliance.*;import com.rpb.reservation.workforce.application.*;
import com.rpb.reservation.workforce.persistence.WorkforceEmployeeRepository;import com.rpb.reservation.workforce.domain.WorkforceException;
import com.rpb.reservation.walkin.api.CurrentActor;import java.time.*;import java.math.BigDecimal;import java.util.*;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class LeaveYearEndService {
 private final WorkforceAccess gate;private final ComplianceAccess access;private final ComplianceRepository policies;private final WorkforceEmployeeRepository employees;private final LeaveAccountRepository repo;private final LeaveBalanceEngine engine;private final LeaveAccountService accounts;private final WorkforceAudit audit;
 public LeaveYearEndService(WorkforceAccess gate,ComplianceAccess access,ComplianceRepository policies,WorkforceEmployeeRepository employees,LeaveAccountRepository repo,LeaveBalanceEngine engine,LeaveAccountService accounts,WorkforceAudit audit){this.gate=gate;this.access=access;this.policies=policies;this.employees=employees;this.repo=repo;this.engine=engine;this.accounts=accounts;this.audit=audit;}
 @Transactional public Page close(CurrentActor a,UUID store,UUID id,YearEnd c){if(id==null||c==null||c.employeeId()==null||c.year()<2000||c.year()>=2100||c.note()==null||c.note().isBlank()||c.note().length()>1000)throw WorkforceException.invalid();gate.sourceWrite(a);var employee=access.employee(a,store,c.employeeId(),true);access.notSelf(a,employee);employees.lock(c.employeeId());policies.lock(a.tenantId(),"command:"+id);var replay=policies.replay(a,store,id,"year-end",c,Page.class);if(replay.isPresent())return replay.get();var first=LocalDate.of(c.year()+1,1,1);if(employee.leaveDate()!=null&&employee.leaveDate().isBefore(first))throw new WorkforceException("LEAVE_EXIT_SETTLEMENT_REQUIRED",409);if(engine.today().isBefore(first))throw new WorkforceException("LEAVE_YEAR_NOT_ENDED",409);var old=repo.accounts(a.tenantId(),c.employeeId(),c.year()).stream().filter(x->x.companyId().equals(employee.companyId())).toList();if(old.isEmpty())throw WorkforceException.missing();var contract=policies.contract(a.tenantId(),c.employeeId(),first).orElseThrow(WorkforceException::missing);var policy=policies.policy(a.tenantId(),contract.policyId(),contract.policyVersion()).orElseThrow();if(!policy.status().equals("published")||first.isAfter(policy.effectiveTo()))throw new WorkforceException("COMPLIANCE_POLICY_EXPIRED",409);
  for(var account:old){if(!account.companyId().equals(contract.companyId())||!(contract.partTime()?"hour":"day").equals(account.unit()))throw new WorkforceException("LEAVE_CONTRACT_REVIEW_REQUIRED",409);var issues=engine.issues(a.tenantId(),account);if(!issues.isEmpty())throw new WorkforceException(issues.getFirst(),409);engine.accrue(a,account);var target=repo.accounts(a.tenantId(),c.employeeId(),c.year()+1).stream().filter(x->x.companyId().equals(account.companyId())&&x.kind().equals(account.kind())).findFirst().orElse(null);if(target==null){var initial=engine.entitlement(a.tenantId(),policy,contract,account.kind(),first);target=new Account(UUID.randomUUID(),account.employeeId(),account.companyId(),c.year()+1,account.kind(),account.unit(),contract.id(),first,initial,1);repo.create(a.tenantId(),a.actorId(),target);if(initial.signum()>0)repo.credit(a.tenantId(),target,"grant","year-start:"+id+":"+account.kind(),engine.expiry(policy,contract,target.year(),target.kind()),initial);}
   for(var lot:repo.lots(a.tenantId(),account.id())){var available=lot.remaining().subtract(lot.reserved()).max(BigDecimal.ZERO);if(available.signum()==0)continue;boolean carry=Set.of("annual","company").contains(account.kind())&&!lot.expiresOn().isBefore(first);repo.entry(a.tenantId(),a.actorId(),account,lot.id(),id.toString(),carry?"carry-out":"expire",available.negate(),c.note());if(carry)repo.credit(a.tenantId(),target,"carry","carry:"+lot.id()+":"+id,lot.expiresOn(),available,lot.entitlementYear());}
  }
  var result=accounts.page(a,store,c.employeeId(),c.year()+1);policies.receipt(a,store,id,"year-end",c,result);audit.changed(a,store,"leave-account.year-end",id,null,c);return result;
 }
}
